on":"sources.intervention_sav.signe"},{"type":"champ","valeur":"=\"Signé sur place le \" & sources.intervention_sav.signe_le","style":"discret","condition":"sources.intervention_sav.signe"},{"type":"image","ressource":"SIGNATURE_SAV","hauteur":30,"largeur":"70mm","condition":"sources.intervention_sav.signe"},{"type":"champ","valeur":"Signature numérique simple : image tracée sur l’écran, horodatée par le serveur ; l’empreinte du présent document est conservée.","style":"petit","condition":"sources.intervention_sav.signe"}]}]}}]}'::jsonb, 'INTERNE', 96, TRUE, 'logibtp', 'logibtp')
ON CONFLICT (med_code) DO UPDATE SET med_libelle = excluded.med_libelle, med_genre = excluded.med_genre, med_cible = excluded.med_cible,
  med_source = excluded.med_source, med_types = excluded.med_types, med_contenu = excluded.med_contenu, med_ordre = excluded.med_ordre,
